package org.apache.commons.jxpath.ri.model.beans;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.QName;
import org.apache.commons.jxpath.AbstractFactory;
import org.apache.commons.jxpath.JXPathAbstractFactoryException;
import org.apache.commons.jxpath.JXPathContext;
import org.apache.commons.jxpath.JXPathIntrospector;
import org.apache.commons.jxpath.NodePointer;
import org.apache.commons.jxpath.ri.QName;
import org.apache.commons.jxpath.ri.model.NodePointer;
import org.apache.commons.jxpath.util.ValueUtils;
import org.junit.*;
import org.junit.Test;
import org.mockito.ArgumentCaptor;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.spy;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

public class PropertyPointer_createChild_TriageGen2Test {

    /**
     * Test case where name is not null.
     * Covers the branch where name != null is true.
     */
    @Test
    public void testCreateChild_WithName() {
        // Arrange
        JXPathContext mockContext = mock(JXPathContext.class);
        NodePointer mockParent = mock(NodePointer.class);
        NodePointer mockExpectedChild = mock(NodePointer.class);
        QName name = new QName("testProperty");
        int index = 5;

        // We spy on the PropertyPointer because the method calls clone() and then works on the cloned object.
        // In a real scenario, PropertyPointer is an abstract class or part of a hierarchy.
        // Since we cannot instantiate an abstract class, we mock/spy a concrete-like implementation.
        PropertyPointer spyProp = spy(new ConcretePropertyPointer(mockParent));

        // Mock the clone() behavior to return another spy of the same type to simulate the property pointer behavior
        PropertyPointer clonedProp = spy(new ConcretePropertyPointer(mockParent));
        when(spyProp.clone()).thenReturn(clonedProp);

        // Mock createPath to return our expected child
        when(clonedProp.createPath(mockContext)).thenReturn(mockExpectedChild);

        // Act
        NodePointer result = spyProp.createChild(mockContext, name, index);

        // Assert
        assertNotNull(result);
        assertEquals(mockExpectedChild, result);

        // Verify property name was set via the cloned object
        verify(clonedProp).setPropertyName(name.toString());
        // Verify index was set via the cloned object
        verify(clonedProp).setIndex(index);
        // Verify createPath was called on the cloned object
        verify(clonedProp).createPath(mockContext);
    }

    /**
     * Test case where name is null.
     * Covers the branch where name != null is false.
     */
    @Test
    public void testCreateChild_WithNameNull() {
        // Arrange
        JXPathContext mockContext = mock(JXPathContext.class);
        NodePointer mockParent = mock(NodePointer.class);
        NodePointer mockExpectedChild = mock(NodePointer.class);
        QName name = null;
        int index = 10;

        PropertyPointer spyProp = spy(new ConcretePropertyPointer(mockParent));
        PropertyPointer clonedProp = spy(new ConcretePropertyPointer(mockParent));
        when(spyProp.clone()).thenReturn(clonedProp);
        when(clonedProp.createPath(mockContext)).thenReturn(mockExpectedChild);

        // Act
        NodePointer result = spyProp.createChild(mockContext, name, index);

        // Assert
        assertNotNull(result);
        assertEquals(mockExpectedChild, result);

        // Verify setPropertyName was NEVER called because name was null
        verify(clonedProp, org.mockito.Mockito.never()).setPropertyName(any(String.class));
        // Verify index was still set
        verify(clonedProp).setIndex(index);
    }

    /**
     * Inner concrete class to allow testing the abstract PropertyPointer logic.
     */
    private static class ConcretePropertyPointer extends PropertyPointer {
        private String propertyName;
        private int index;

        public ConcretePropertyPointer(NodePointer parent) {
            super(parent);
        }

        @Override
        public void setPropertyName(String propertyName) {
            this.propertyName = propertyName;
        }

        @Override
        public String getPropertyName() {
            return propertyName;
        }

        @Override
        public void setIndex(int index) {
            this.index = index;
        }

        @Override
        public int getPropertyIndex() {
            return index;
        }

        @Override
        public NodePointer createPath(JXPathContext context) {
            return null; 
        }

        // Stubbing required abstract methods for the mock/spy to function
        @Override public Object getBean() { return null; }
        @Override public QName getName() { return null; }
        @Override public int getPropertyCount() { return 0; }
        @Override public String[] getPropertyNames() { return new String[0]; }
        @Override protected boolean isActualProperty() { return false; }
        @Override public boolean isActual() { return true; }
        @Override public Object getImmediateNode() { return null; }
        @Override public boolean isCollection() { return false; }
        @Override public boolean isLeaf() { return false; }
        @Override public int getLength() { return 0; }
        @Override public NodePointer getImmediateValuePointer() { return null; }
        @Override public NodePointer createPath(JXPathContext context, Object value) { return null; }
        @Override public NodePointer createChild(JXPathContext context, QName name, int index, Object value) { return null; }
    }
}
